import{G as e,W as t,n,rt as r}from"./chunks/framework.DpaCCLuo.js";import"./chunks/assets.DvAxJGtb.js";var i=JSON.parse(`{"title":"インストール","description":"","frontmatter":{},"headers":[],"relativePath":"installation.md","filePath":"installation.md"}`),a={name:`installation.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to “インストール”">​</a></h1><h2 id="_1-前提ツールを導入する" tabindex="-1">1. 前提ツールを導入する <a class="header-anchor" href="#_1-前提ツールを導入する" aria-label="Permalink to “1. 前提ツールを導入する”">​</a></h2><p>VRChat Creator Companion（VCC）で作ったアバター用のプロジェクトには、VRChat SDK が最初から入っています。そのプロジェクトに Modular Avatar（MA）を追加してください。</p><p>MAの追加方法は <a href="https://modular-avatar.nadena.dev/ja/docs/intro" target="_blank" rel="noreferrer">公式ドキュメントの「インストール」</a> にあります。</p><p>対応するバージョンは<a href="./requirements">対応環境</a>を参照してください。</p><h2 id="_2-unitypackage-をインポートする" tabindex="-1">2. unitypackage をインポートする <a class="header-anchor" href="#_2-unitypackage-をインポートする" aria-label="Permalink to “2. unitypackage をインポートする”">​</a></h2><p>ダウンロードした unitypackage をUnityのProjectウィンドウへドラッグ＆ドロップし、すべて選択したままImportします。</p><p><img src="/mururu-blink-lipsync/images/1-2.png" alt="Import Unity Package の画面" width="352" height="582"></p><h2 id="_3-ツールのウィンドウを開く" tabindex="-1">3. ツールのウィンドウを開く <a class="header-anchor" href="#_3-ツールのウィンドウを開く" aria-label="Permalink to “3. ツールのウィンドウを開く”">​</a></h2><p>メニューの <strong>Tools &gt; Mururu Blink &amp; LipSync</strong> を選びます。</p><p><img src="/mururu-blink-lipsync/images/1-3.png" alt="Tools メニューの Mururu Blink &amp; LipSync" width="776" height="210"></p><h2 id="_4-ムルルを選択してインストールする" tabindex="-1">4. ムルルを選択してインストールする <a class="header-anchor" href="#_4-ムルルを選択してインストールする" aria-label="Permalink to “4. ムルルを選択してインストールする”">​</a></h2><p>Hierarchyでシーンに置いたムルルを選択すると、「対象アバター」に自動で入ります。「状態: 未導入」と表示されていることを確認して、<strong>インストール</strong> を押します。</p><p><img src="/mururu-blink-lipsync/images/1-4.png" alt="未導入の状態のMururu Blink &amp; LipSyncウィンドウ" width="482" height="574"></p><p>「インストールが完了しました。」と表示されれば完了です。アバター直下に <code>MururuBlinkLipSync</code> が追加されます。そのままVRChatへアップロードできます。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>シーンに置いたムルルが1体だけなら、ウィンドウを開いた時点で自動で対象になります。Prefabアセットは対象にできません。</p></div><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>インストールすると、ツールのフォルダ内の <code>Generated</code> に生成ファイルが作られます。手動で削除したり、自作のAnimator Controllerなどから使ったりしないでください。修復やアンインストールのときに、置き換えや削除をすることがあります。</p></div>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};